arguments.argument:
part_x1 = view_xview*xscale
part_y1 = view_yview*yscale
part_x2 = (view_xview+view_wview)*xscale
part_y2 = (view_yview+view_hview)*yscale
//미니맵에서의 현재 위치 계산

x_loc = view_xview + x_loc2
y_loc = view_yview + y_loc2
//화면 상 미니맵 가로,세로 위치

x=x_loc
y=y_loc
//현재 위치 이동

if min_fog_time=0 and global.min_fog_check=1
{
minimap_fog2=sprite_duplicate(spr_minimap_fog2)
sk_land_destroy(minimap_fog2, c_white)
sk_land_destroy(minimap_fog1, c_white)
min_fog_time=global.min_fog_alarm
draw_sprite_ext(spr_interface, -1, view_xview+320, view_yview+415, 1, 1, 0, -1, 1)
}
//미니맵 포그파괴

if min_fri_time=0
{
sk_m_fog_bk_update(min_back_fog)
min_fri_time=global.min_f_back_alarm
}
//미니맵 지형을 업데이트함

draw_sprite(min_back_fog, -1, x, y)
//미니맵 지형을그림

if global.min_fog_check=1
{
if global.fog2_check=1{draw_sprite_ext(minimap_fog2, 0, x, y, 1, 1, 0, c_dkgray, 0.5)}
if global.fog_check=1{draw_sprite(minimap_fog1, -1, x, y)}
//미니맵 포그 그리기
}

draw_set_color(c_orange)
draw_rectangle(x_loc-0.5, y_loc-0.5, x_loc+0.5 + width, y_loc+0.5 + height, true)
//미니맵 테두리 표시

if sys_mouse.click=1
{
draw_set_alpha(0.3)
draw_set_color(c_green)
draw_rectangle(global.drag_x*xscale+x_loc,global.drag_y*yscale+y_loc,sys_mouse.x*xscale+x_loc,sys_mouse.y*yscale+y_loc,0)
draw_set_alpha(1)
//드래그창
draw_set_color(c_red)
draw_rectangle(global.drag_x*xscale+x_loc,global.drag_y*yscale+y_loc,sys_mouse.x*xscale+x_loc,sys_mouse.y*yscale+y_loc,1)
//드래그틀
}
//드래그 위치표시

draw_set_color(c_orange)
draw_rectangle(x_loc + part_x1, y_loc + part_y1, x_loc + part_x2,  y_loc + part_y2, true)
//미니맵 현재 영역 표시

draw_set_color(c_black)
